List<Map<String, dynamic>> topCoins({required List<Transaction> transactions}) {
  Map<String, List<double>> coinProfits = {};
  Map<String, List<double>> coinLosses = {};

  for (Transaction transaction in transactions) {
    if (!coinProfits.containsKey(transaction.coinName)) {
      coinProfits[transaction.coinName] = <double>[];
      coinLosses[transaction.coinName] = <double>[];
