    const keyB = b[0];

    // Compare keys in desired order (ascending or descending)
    return (typeof order === 'string' && order === 'desc') ? (keyB < keyA ? -1 : (keyB > keyA ? 1 : 0)) : (keyA < keyB ? -1 : (keyA > keyB ? 1 : 0));
